  const runs = await currentRuns();
  const running = liveHub(runs);
  const other = foreignSession(runs, running);
  if (other) {
    alert('Другая сессия уже использует раннер. Остановите её перед запуском NPM-Hub.');
    return;
  }
  if (running.length) {
    if (!confirm(`NPM-Hub уже идёт (${mins(running[0].created_at)} мин).\n\n` +
