function handoffPanelRender(doc) {
  const line = $('ho-line');
  if (!line) return;
  const p = (doc && doc.policy) || {};
  const s = (doc && doc.status) || null;
  const set = (id, v) => { const el = $(id); if (el && document.activeElement !== el) el.value = v == null ? '' : v; };
  set('ho-age', p.maxAgeMin); set('ho-idle', p.idleMin); set('ho-count', p.countdownSec);
  const auto = $('ho-auto');
  if (auto && document.activeElement !== auto) auto.checked = p.auto === true || p.auto === 1;
  if (!s) {
    line.textContent = doc
      ? (p.auto ? 'раннер ещё не публиковал состояние — лимиты сохранены, передача начнётся сама'
                : 'раннер ещё не публиковал состояние — автопередача выключена, раннер живёт, пока жив GitHub')
      : 'handoff.json ещё нет: сохрани лимиты, и раннер подхватит их';
    return;
  }
  const bits = [];
  bits.push('<b>' + esc(HO_STATE_TEXT[s.state] || s.state || '—') + '</b>');
  if (s.state === 'countdown') {
    // leftSec публикуется раз в минуту, поэтому считаем от абсолютного дедлайна.
    const left = s.deadlineAt ? Math.max(0, (s.deadlineAt - Date.now()) / 1000) : (s.leftSec || 0);
    bits.push('осталось <b>' + hoMmss(left) + '</b>');
  }
  if (s.reason) bits.push(esc(HO_WHY[s.reason] || s.reason));
  if (s.lastError) bits.push('<span class="danger">' + esc(s.lastError) + '</span>');
  if (s.successor && s.successor.url) bits.push('новый: <a href="' + esc(s.successor.url) + '" target="_blank" rel="noreferrer">' + esc(s.successor.url) + '</a>');
  if (s.savedIn) bits.push('настройки: ' + (s.savedIn === 'repo' ? 'в репозитории' : 'локально у раннера'));
  bits.push(s.enabled ? 'автопередача включена' : 'автопередача выключена — сам ничего не запускаю');
  line.innerHTML = bits.join(' · ');
  const cont = $('ho-continue');
  if (cont) cont.disabled = !(s.state === 'countdown' || s.state === 'failed');
  const start = $('ho-start');
  if (start) start.disabled = !(s.state === 'idle' || s.state === 'failed');
}
async function handoffPanelPoll() {
  if (page !== 'sess') return;
  try { handoffPanelRender(await readHandoffDoc()); }
  catch (e) { if (e && e.is403) sessPausedUntil = Date.now() + (e.unbanMs || 600000); }
}
async function handoffPanelSave() {
  const num = (id, def) => { const v = parseInt(($(id) || {}).value, 10); return Number.isFinite(v) ? v : def; };
  const hint = $('ho-hint');
  // The saved object replaces the policy wholesale, so carry the fields the
  // panel does not edit (standby/retry) over instead of resetting them.
  let old = {};
  try { const cur = await readHandoffDoc(); old = (cur && cur.policy) || {}; } catch (e) {}
  const policy = {
    auto: !!($('ho-auto') || {}).checked,
    maxAgeMin: num('ho-age', 0),
    idleMin: num('ho-idle', 0),
    countdownSec: num('ho-count', 180),
    standbyMin: old.standbyMin,
    retryMin: old.retryMin
  };
  try {
    await writeHandoffDoc({ policy });
    if (hint) hint.textContent = policy.auto
      ? 'сохранено в control-репозитории — сессия под лимитом переедет сама, пока вы за ней работаете'
      : 'сохранено: автопередача выключена, без вашего нажатия новый раннер не запустится';
  } catch (e) {
    if (hint) hint.textContent = 'не сохранилось: ' + e.message;
  }
  handoffPanelPoll();
}

